import type { Ink } from '@/lib/ink/builder'
import { paint } from '@/lib/ink/paint'
import { hashSeed } from '@/lib/ink/rng'
import type { Box } from '@/lib/ink/recipes'
import type { Line, PenName, Pt } from '@/lib/ink/types'

export const REVEAL_DASH = '[&>svg_[data-part=reveal]]:[stroke-dasharray:1]'
export const REVEAL_WHEN_CHECKED = 'data-touched:data-[state=checked]:[&>svg_[data-part=reveal]]:animate-[ll-draw_var(--ll-dur-sheet)_var(--ll-ease-out)_both]'
export const REVEAL_WHEN_INDETERMINATE = 'data-touched:data-[state=indeterminate]:[&>svg_[data-part=reveal]]:animate-[ll-draw_var(--ll-dur-sheet)_var(--ll-ease-out)_both]'
export const REVEAL_WHEN_ON = 'data-touched:data-[state=on]:[&>svg_[data-part=reveal]]:animate-[ll-draw_var(--ll-dur-sheet)_var(--ll-ease-out)_both]'

export function markTouched(e: { currentTarget: Element }): void {
  e.currentTarget.setAttribute('data-touched', '')
}

export function revealId(seed: string, name: string): string {
  return `ll-rv-${hashSeed(seed).toString(36)}${name}`
}

export interface RevealOpts {
  id: string
  lines: Line[]
  pen: PenName
  box: Box
  width?: number
  revealWidth?: number
}

export function reveal(ink: Ink, o: RevealOpts): void {
  const sym = ink.define(() => ink.lines(o.lines, o.pen, { width: o.width }))
  const d = o.lines.map((l) => l.pts.map((p: Pt, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join('')).join('')
  const pad = 12
  const sw = o.revealWidth ?? Math.max(3.4, Math.min(o.box.w, o.box.h) * 0.3)
  ink.raw(
    `<mask id="${o.id}" maskUnits="userSpaceOnUse" x="${-pad}" y="${-pad}" width="${o.box.w + 2 * pad}" height="${o.box.h + 2 * pad}">` +
      `<path data-part="reveal" d="${d}" pathLength="1" fill="none" stroke="${paint('photo')}" stroke-width="${sw.toFixed(1)}" stroke-linejoin="round"/>` +
      `</mask>`,
    'under',
  )
  ink.raw(`<g mask="url(#${o.id})"><use href="#${sym}"/></g>`, 'top')
}

import { underline } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'

export const fieldErrorRecipe = defineRecipe<Record<string, never>>({
  id: 'field-error',
  kind: 'underline',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, _p, ctx) {
    ink.layer('rest', () => {
      underline(ink, -1, h + 0.5, w + 2, { kind: ctx.calm ? 'single' : 'wavy', pen: ctx.calm ? 'red.fine' : 'redfelt.fine', opts: { simple: w > 200 } })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { box, dashedBox, focusRing, squiggle, RULER } from '@/lib/ink/shapes'
import type { Ink } from '@/lib/ink/builder'
import type { RecipeContext, Box } from '@/lib/ink/recipes'

export interface FieldFrameParams {
  disabled?: boolean
  invalid?: boolean
  readOnly?: boolean
  multiline?: boolean
  ruled?: boolean
  lineHeight?: number
  ruleTop?: number
  grip?: boolean
}

const RULE_OFFSET = 0.74

function ruledLines(ink: Ink, w: number, h: number, p: FieldFrameParams, alpha: number): void {
  const lh = p.lineHeight ?? 28
  const top = p.ruleTop ?? 8
  const bottom = h - 4
  for (let i = 0; ; i++) {
    const y = top + i * lh + lh * RULE_OFFSET
    if (y > bottom) break
    ink.stroke([[8, y], [w - 8, y]], 'pencil.fine', { ...RULER, color: 'rule-blue', alpha, width: 1.05, simple: true })
  }
}

function grip(ink: Ink, w: number, h: number, rtl: boolean): void {
  const X = (x: number): number => (rtl ? w - x : x)
  ink.stroke([[X(w - 12), h - 3.4], [X(w - 3.4), h - 12]], 'pencil.fine', { ...RULER, alpha: 0.85, simple: true })
  ink.stroke([[X(w - 7.6), h - 3.2], [X(w - 3.2), h - 7.6]], 'pencil.fine', { ...RULER, alpha: 0.85, simple: true })
}

function bang(ink: Ink, x: number, y: number): void {
  ink.stroke([[x, y - 7.5], [x + 0.6, y + 1.6]], 'redfelt', { end: 'flick', wobble: 0.2, width: 1.7 })
  ink.dot(x + 0.8, y + 6.8, 1.5, 'redfelt')
}

export function drawFieldFrame(ink: Ink, { w, h }: Box, p: FieldFrameParams, ctx: RecipeContext): void {
  const r = clamp(Math.min(w, h) * 0.08, 2, 4)
  const body = roundRectPoly(1.5, 1.5, w - 3, h - 3, r)
  const ruled = p.ruled && !!p.multiline
  const rtl = ctx.dir === 'rtl'

  if (p.disabled) {
    if (ctx.lazyOnly) return
    ink.layer('disabled', () => {
      wash(ink, body, 'paper-shade', { alpha: 0.9, material: 'wash' })
      if (ruled) ruledLines(ink, w, h, p, 0.55)
      dashedBox(ink, 0, 0, w, h, { r, pen: 'pencil', opts: { color: 'pencil-mark' } })
      if (p.grip) grip(ink, w, h, rtl)
    })
    return
  }

  ctx.lazy('focus', (fink) => focusRing(fink, 0, 0, w, h, { r }))
  if (!p.readOnly) {
    ctx.lazy('hover', (hink) =>
      box(hink, 0.6, 0.6, w - 1.2, h - 1.2, { pen: p.invalid ? 'red.fine' : 'ink.fine', corner: r, loose: 0.7, opts: { alpha: p.invalid ? 0.7 : 0.75 } }),
    )
  }
  if (ctx.lazyOnly) return

  const bangY = p.multiline ? 18 : h / 2
  if (p.invalid) {
    ink.layer('invalid', () => {
      ink.poly('under', body, 'slip', 0.7)
      if (ruled) ruledLines(ink, w, h, p, 0.8)
      box(ink, 0, 0, w, h, { pen: ctx.calm ? 'red.fine' : 'red', corner: r, opts: { width: ctx.calm ? 1.1 : 1.25 } })
      const len = clamp(w - 40, 24, 110)
      if (!ctx.calm) squiggle(ink, rtl ? w - 6 - len : 6, h + 5, len, { pen: 'redfelt.fine', h: 7, amp: 0.8 })
      if (w >= 72) bang(ink, rtl ? 18 : w - 18, bangY)
      if (p.grip) grip(ink, w, h, rtl)
    })
    return
  }

  ink.layer('rest', () => {
    if (p.readOnly) {
      wash(ink, body, 'paper-shade', { alpha: 0.6, material: 'wash' })
      if (ruled) ruledLines(ink, w, h, p, 0.8)
      box(ink, 0, 0, w, h, { pen: 'pencil.fine', corner: r, opts: { alpha: 0.8 } })
    } else {
      ink.poly('under', body, 'slip', 0.7)
      if (ruled) ruledLines(ink, w, h, p, 1)
      if (ctx.calm) box(ink, 0, 0, w, h, { pen: 'pencil.fine', corner: r })
      else box(ink, 0, 0, w, h, { pen: 'pencil', corner: r, opts: { width: 1.15 } })
    }
    if (p.grip) grip(ink, w, h, rtl)
  })
}

import { defineRecipe } from '@/lib/ink/recipes'
import { reveal, revealId, REVEAL_DASH } from '@/lib/ink/recipes/draw-on-ink'
import { bracketLines } from '@/lib/ink/shapes'
import type { Line } from '@/lib/ink/types'

export interface MarginBracketParams {
  kind: 'square' | 'curly'
}

export const MARGIN_BRACKET_DRAW = `${REVEAL_DASH} in-data-touched:[&>svg_[data-part=reveal]]:animate-[ll-draw_var(--ll-dur-draw)_var(--ll-ease-out)_both]`

export const marginBracketRecipe = defineRecipe<MarginBracketParams>({
  id: 'margin-bracket',
  kind: 'bracket',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }, { kind }, ctx) {
    const rtl = ctx.dir === 'rtl'
    const dir = rtl ? -1 : 1
    const x = rtl ? w - 1.5 : 1.5
    const lines: Line[] = bracketLines(ink.next('bracket'), x, 1, Math.max(8, h - 2), { kind, dir })
    ink.layer('rest', () => {
      reveal(ink, {
        id: revealId(ctx.seed, 'b'),
        lines,
        pen: ctx.calm ? 'bluepencil.fine' : 'bluepencil',
        width: ctx.calm ? 1.1 : 1.65,
        box: { w, h },
        revealWidth: Math.max(4, Math.min(w, 14)),
      })
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import { paint } from '@/lib/ink/paint'
import { hashSeed } from '@/lib/ink/rng'
import type { Line, PenName, PenSpec, Pt, StrokeOpts } from '@/lib/ink/types'

export interface MarkRevealOpts {
  id: string
  lines: Line[]
  pen: PenName | PenSpec
  box: { w: number; h: number }
  pad: number
  width?: number
  opts?: StrokeOpts
  revealWidth?: number
}

export function markRevealId(seed: string, name: string): string {
  return `ll-mr-${hashSeed(seed).toString(36)}${name}`
}

export function revealMark(ink: Ink, o: MarkRevealOpts): void {
  const sym = ink.define(() => ink.lines(o.lines, o.pen, { ...o.opts, width: o.width }))
  const d = o.lines.map((l) => l.pts.map((p: Pt, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join('')).join('')
  ink.raw(
    `<mask id="${o.id}" maskUnits="userSpaceOnUse" x="${-o.pad}" y="${-o.pad}" width="${o.box.w + 2 * o.pad}" height="${o.box.h + 2 * o.pad}">` +
      `<path data-part="reveal" d="${d}" pathLength="1" fill="none" stroke="${paint('photo')}" stroke-width="${(o.revealWidth ?? 6).toFixed(1)}" stroke-linejoin="round" stroke-linecap="round"/>` +
      `</mask>`,
    'under',
  )
  ink.raw(`<g mask="url(#${o.id})"><use href="#${sym}"/></g>`, 'top')
}

import { Ink, type InkResult } from '@/lib/ink/builder'
import { highlight } from '@/lib/ink/fills'
import { arrow, cross, focusRing } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import type { Tier } from '@/lib/ink/types'

export interface CloseMarkParams {
  tone?: 'ink' | 'red'
}

export const closeMarkRecipe = defineRecipe<CloseMarkParams>({
  id: 'overlay-close',
  kind: 'close',
  layers: ['rest', 'hover', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { tone = 'ink' }, ctx) {
    const cx = w / 2
    const cy = h / 2
    ctx.lazy('focus', (f) => focusRing(f, cx - 12, cy - 12, 24, 24, { shape: 'ellipse', gap: 1.5 }))
    if (ctx.lazyOnly) return
    const s = ctx.calm ? 11 : 12.5
    ink.layer('rest', () => {
      cross(ink, cx - s / 2, cy - s / 2, s, { pen: tone === 'red' ? 'redfelt' : ctx.calm ? 'ink.fine' : 'ink', opts: { width: ctx.calm ? 1.1 : 1.35, start: 'soft' } })
    })
    ink.layer('hover', () => {
      highlight(ink, cx - 12, cy - 8.5, 24, 17, { pen: 'hi', opts: { alpha: 0.85 } })
    })
  },
})

export interface PointerMarkOptions {
  w?: number
  h?: number
  tier?: Tier
  calm?: boolean
}

export function pointerMark(seed: string | number, o: PointerMarkOptions = {}): InkResult {
  const w = o.w ?? 22
  const h = o.h ?? 20
  const ink = new Ink(seed, { tier: o.tier, calm: o.calm })
  const r = ink.next('pointer')
  const x = w / 2 + r.gauss(0, 0.5)
  arrow(ink, x - 0.6, 0.6, x + r.range(-0.4, 1), h - 1.8, { pen: 'ink', head: 'v', headLen: Math.min(10.5, h * 0.56), curve: r.range(0.1, 0.17), opts: { width: 1.6 } })
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 3 })
}

import { Ink } from '@/lib/ink/builder'
import { loopLines, RULER } from '@/lib/ink/shapes'
import type { Line, Pt } from '@/lib/ink/types'

export const EDGE_LEN = 96
export const EDGE_TH = 5
export const HATCH = 40
export const CIRCLE = 64

const CURRENT = { color: 'current' as const }

function tile(seed: string, w: number, h: number, draw: (ink: Ink) => void, tier: 'lo' | 'hi' = 'lo', stretch = false): string {
  const ink = new Ink(seed, { tier, grain: false })
  ink.layer('rest', () => draw(ink))
  const svg = ink.toSvg({ w, h, pad: 0 }).svg
  const fit = stretch ? ' preserveAspectRatio="none"' : ''
  const doc = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"${fit}>${svg}</svg>`
  return `url("data:image/svg+xml,${encodeURIComponent(doc)}")`
}

export function edgeTile(seed: string, vertical: boolean): string {
  const w = vertical ? EDGE_TH : EDGE_LEN
  const h = vertical ? EDGE_LEN : EDGE_TH
  const c = EDGE_TH / 2
  const ends: Pt[] = vertical ? [[c, -16], [c, EDGE_LEN + 16]] : [[-16, c], [EDGE_LEN + 16, c]]
  return tile(seed, w, h, (ink) => ink.stroke(ends, 'pencil', { ...CURRENT, ...RULER, width: 0.95, simple: true }), 'lo', true)
}

export function hatchTile(seed: string): string {
  return tile(seed, HATCH, HATCH, (ink) => {
    const rng = ink.next('hatch')
    const gap = HATCH / 5
    const J = Array.from({ length: 5 }, () => rng.gauss(0, 0.35))
    const width = rng.range(0.86, 1.02)
    const slot = (i: number): number => J[((i % 5) + 5) % 5]
    const lines: Line[] = []
    for (let i = -4; i <= 9; i++) {
      const x0 = i * gap
      const top = slot(i), bot = slot(i - 3)
      const slope = (bot - top) / HATCH
      const a: Pt = [x0 + (HATCH + 24) * 0.6 + top - slope * 24, -24]
      const b: Pt = [x0 - 24 * 0.6 + bot + slope * 24, HATCH + 24]
      lines.push({
        pts: [a, [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2], b],
        o: { simple: true, start: 'soft', end: 'soft', speed: 1.1, wobble: 0.1, width },
      })
    }
    ink.lines(lines, 'pencil', { ...CURRENT })
  }, 'hi')
}

export function circleTile(seed: string): string {
  return tile(seed, CIRCLE, CIRCLE, (ink) => {
    const lines = loopLines(ink.next('circle'), CIRCLE / 2, CIRCLE / 2, CIRCLE / 2 - 5, CIRCLE / 2 - 5, { clean: true })
    ink.lines(lines, 'pencil', { ...CURRENT, width: 1.05, simple: true })
  })
}

import { blobFill } from '@/lib/ink/fills'
import { defineRecipe } from '@/lib/ink/recipes'
import type { PaintKey } from '@/lib/ink/paint'
import { seg } from '@/lib/ink/geom'
import type { Pt } from '@/lib/ink/types'

export interface RevealNibParams {
  color?: PaintKey
}

export const revealNibRecipe = defineRecipe<RevealNibParams>({
  id: 'reveal-nib',
  kind: 'reveal-nib',
  layers: ['rest'],
  pad: 4,
  draw(ink, { w, h }, { color = 'tomato' }) {
    const s = Math.min(w, h) / 24
    const P = (x: number, y: number): Pt => [x * s, y * s]
    ink.layer('rest', () => {
      blobFill(ink, [P(6.5, 17.5), P(18.5, 3.5), P(22.5, 6.5), P(9.5, 19.5)], 'paper', { alpha: 0.95, mis: 0.6, material: 'wash' })
      blobFill(ink, [P(15.4, 7.1), P(18.5, 3.5), P(22.5, 6.5), P(19.2, 10)], color, { alpha: 0.95, mis: 0.5, material: 'wash' })
      ink.lines(
        [
          { pts: seg(...P(6.5, 17.5), ...P(18.5, 3.5), 0.2, 5), o: { start: 'soft', end: 'soft' } },
          { pts: seg(...P(9.5, 19.5), ...P(22.5, 6.5), 0.2, 5), o: { start: 'soft', end: 'soft' } },
          { pts: seg(...P(18.5, 3.5), ...P(22.5, 6.5), 0.1, 3), o: { start: 'soft', end: 'soft' } },
          { pts: [P(6.5, 17.5), P(3.2, 21.4), P(9.5, 19.5)], o: { poly: true, round: 0.4 } },
        ],
        'ink.fine',
        { width: 0.9 },
      )
      ink.dot(...P(3.4, 21.6), 1.5 * s, 'ink', { width: 1 })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { box, focusRing, squiggle, RULER } from '@/lib/ink/shapes'
import type { Box, RecipeContext } from '@/lib/ink/recipes'
import type { Ink } from '@/lib/ink/builder'
import { drawFieldFrame } from '@/lib/ink/recipes/field-frame-ink'

export interface SelectFrameParams {
  disabled?: boolean
  invalid?: boolean
  openable?: boolean
  cell?: number
}

function divider(ink: Ink, x: number, h: number, alpha: number): void {
  ink.stroke([[x, 7], [x, h - 7]], 'pencil.fine', { ...RULER, alpha, simple: true })
}

function bang(ink: Ink, x: number, y: number): void {
  ink.stroke([[x, y - 7.5], [x + 0.6, y + 1.6]], 'redfelt', { end: 'flick', wobble: 0.2, width: 1.7 })
  ink.dot(x + 0.8, y + 6.8, 1.5, 'redfelt')
}

export function drawSelectFrame(ink: Ink, box_: Box, p: SelectFrameParams, ctx: RecipeContext): void {
  const { w, h } = box_
  const cell = p.cell ?? 32
  const rtl = ctx.dir === 'rtl'
  const tickX = rtl ? cell : w - cell
  const roomy = w >= cell * 2.4
  const r = clamp(Math.min(w, h) * 0.08, 2, 4)
  const body = roundRectPoly(1.5, 1.5, w - 3, h - 3, r)

  if (p.invalid && !p.disabled) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, w, h, { r }))
    ctx.lazy('hover', (hv) => box(hv, 0.6, 0.6, w - 1.2, h - 1.2, { pen: 'red.fine', corner: r, loose: 0.7, opts: { alpha: 0.7 } }))
    if (ctx.lazyOnly) return
    ink.layer('invalid', () => {
      ink.poly('under', body, 'slip', 0.7)
      box(ink, 0, 0, w, h, { pen: ctx.calm ? 'red.fine' : 'red', corner: r, opts: { width: ctx.calm ? 1.1 : 1.25 } })
      const len = clamp(w - cell - 32, 24, 110)
      if (!ctx.calm) squiggle(ink, rtl ? w - 6 - len : 6, h + 5, len, { pen: 'redfelt.fine', h: 7, amp: 0.8 })
      if (roomy) bang(ink, rtl ? cell + 14 : w - cell - 14, h / 2)
    })
    return
  }

  drawFieldFrame(ink, box_, { disabled: p.disabled }, ctx)
  if (ctx.lazyOnly) return
  if (roomy) ink.layer(p.disabled ? 'disabled' : 'rest', () => divider(ink, tickX, h, p.disabled ? 0.6 : 0.8))
  if (p.disabled || !p.openable) return
  ink.layer('open', () => {
    wash(ink, body, 'hi', { alpha: ctx.calm ? 0.3 : 0.5 })
    box(ink, 0.6, 0.6, w - 1.2, h - 1.2, { pen: ctx.calm ? 'pencil.fine' : 'ink.fine', corner: r, loose: 0.7, opts: { alpha: 0.85 } })
  })
}

import type { PenName, PenSpec, StrokeOpts } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'

export interface LineMetrics {
  fs: number
  base: number
  xh: number
  cap: number
  desc: number
  ch: number
}

export interface LineParams extends LineMetrics {
  first: boolean
  last: boolean
  n: number
  animate?: boolean
}

export interface FontRatios {
  asc: number
  desc: number
  xh: number
  cap: number
  pdesc: number
}

export const GUESS_RATIOS: FontRatios = { asc: 1.06, desc: 0.53, xh: 0.52, cap: 0.74, pdesc: 0.22 }

export function lineMetrics(h: number, fs: number, r: FontRatios = GUESS_RATIOS): LineMetrics {
  const total = r.asc + r.desc || 1
  return {
    fs: Math.max(6, Math.round(fs)),
    ch: Math.round(h),
    base: Math.round((r.asc / total) * h),
    xh: Math.max(2, Math.round(r.xh * fs)),
    cap: Math.max(3, Math.round(r.cap * fs)),
    desc: Math.max(1, Math.round(r.pdesc * fs)),
  }
}

export type HighlightTone = 'yellow' | 'pink' | 'green' | 'blue' | 'orange' | 'lilac' | 'teal'

export const HIGHLIGHT_TONES: Record<HighlightTone, { color?: PaintKey; alpha: number }> = {
  yellow: { alpha: 1 },
  pink: { color: 'bubblegum', alpha: 0.8 },
  green: { color: 'grass', alpha: 0.7 },
  blue: { color: 'sky', alpha: 0.75 },
  orange: { color: 'tangerine', alpha: 0.75 },
  lilac: { color: 'grape', alpha: 0.6 },
  teal: { color: 'teal', alpha: 0.7 },
}

export type MarkPen = 'ink' | 'blue' | 'red' | 'green' | 'pencil' | 'marker' | 'orange'
export type MarkWeight = 'fine' | 'regular' | 'brush'

const FELT: Record<MarkPen, PenName> = {
  ink: 'ink',
  blue: 'blue',
  red: 'redfelt',
  green: 'greenfelt',
  pencil: 'pencil',
  marker: 'terracotta',
  orange: 'orange',
}
const PENCIL: Partial<Record<MarkPen, PenName>> = { red: 'red', green: 'green' }

export function markPen(tone: MarkPen, weight: MarkWeight, fs: number, o: { pencil?: boolean } = {}): { pen: PenName; width: number; dry: number } {
  const k = Math.min(1.7, Math.max(0.85, fs / 18))
  if (tone === 'marker') return { pen: 'terracotta', width: 0.3 * k, dry: 1 }
  const base = (o.pencil && PENCIL[tone]) || FELT[tone]
  const w = weight === 'regular' && fs < 15 ? 'fine' : weight
  return { pen: w === 'regular' ? base : (`${base}.${w}` as PenName), width: k, dry: 1 }
}

export const STRUCTURAL_DRY = 0.3

export function highlighterPen(tone: HighlightTone): { pen: PenName | PenSpec; opts: StrokeOpts } {
  const t = HIGHLIGHT_TONES[tone] ?? HIGHLIGHT_TONES.yellow
  return { pen: 'hi', opts: t.color ? { color: t.color, alpha: t.alpha } : {} }
}

export function overshoot(fs: number): number {
  return Math.max(1.5, fs * 0.14)
}
